/**
 * sequenceNumber.ts — helpers for human-readable sequential numbers such as
 * INS-2026-042, OWS-2026-017 or PMA-2026-003.
 *
 * Why this exists: these numbers were generated by taking MAX(column) as a *string* and adding one.
 * String ordering puts "1000" before "999", so once a sequence reached 999 the "maximum" stopped
 * advancing, every new number collided with an existing one, and — because the columns are unique —
 * every later insert failed. The numeric suffix is compared as an integer here instead.
 *
 * Two requests can still derive the same number at the same instant, so callers should wrap the
 * insert in withNumberRetry(): the unique constraint rejects the loser, which then simply re-reads
 * the maximum and takes the next number.
 */

import { sql } from "drizzle-orm";
import type { AnyPgColumn } from "drizzle-orm/pg-core";
import { db } from "../db";

/** The highest numeric suffix used so far for numbers shaped `${prefix}-<digits>`, or 0 if none. */
export async function maxSequenceSuffix(table: any, column: AnyPgColumn, prefix: string): Promise<number> {
  const [row] = await db
    .select({ n: sql<number>`COALESCE(MAX(CAST(split_part(${column}, '-', 3) AS integer)), 0)` })
    .from(table)
    .where(sql`${column} ~ ${`^${prefix}-[0-9]+$`}`);
  return Number(row?.n ?? 0);
}

/** Postgres unique-violation, whether the driver throws it raw or wrapped. */
export function isUniqueViolation(e: any): boolean {
  return (e?.code ?? e?.cause?.code) === "23505";
}

/** Run an insert that derives its own number, retrying if a concurrent insert took the same one. */
export async function withNumberRetry<T>(attempt: () => Promise<T>, tries = 5): Promise<T> {
  for (let i = 1; ; i++) {
    try {
      return await attempt();
    } catch (e) {
      if (!isUniqueViolation(e) || i >= tries) throw e;
    }
  }
}
